const question = $json.user_question.toLowerCase();

let intent = 'general';
let needs_ansible = false;
let needs_rag = false;

if (question.includes('ansible')) {
  intent = 'ansible_query';
  needs_ansible = true;
}
else if (question.includes('套件') || question.includes('package') || question.includes('軟體') || question.includes('版本')) {
  intent = 'ansible_query';
  needs_ansible = true;
}
else if (question.includes('文檔') || question.includes('document') || question.includes('檢索') || question.includes('search')) {
  intent = 'rag_search';
  needs_rag = true;
}
else {
  intent = 'hybrid';
  needs_ansible = true;
  needs_rag = true;
}

return {
  json: {
    user_question: $json.user_question,
    unit: $json.unit,
    intent: intent,
    needs_ansible: needs_ansible,
    needs_rag: needs_rag
  }
};

const extractNode = $('提取輸入');
const intentNode = $('分析意圖');
const ansibleNode = $('查詢 Ansible DB');
const ragNode = $('查詢 RAG 知識庫');

if (!extractNode || !extractNode.first()) {
  throw new Error('無法取得「提取輸入」節點資料');
}

const question = extractNode.first().json.user_question;
const unit = extractNode.first().json.unit;
const intent = intentNode && intentNode.first() ? intentNode.first().json.intent : 'unknown';

const ansibleItems = ansibleNode ? ansibleNode.all() : [];
let ansible = { success: true, results: [], count: 0 };

for (const item of ansibleItems) {
  if (item.json && item.json.hostname) {
    ansible.results.push({
      id: item.json.id || '',
      hostname: item.json.hostname,
      ip: item.json.ip,
      package_name: item.json.package_name,
      version: item.json.version
    });
  }
}
ansible.count = ansible.results.length;

const ragItems = ragNode ? ragNode.all() : [];
let rag = { success: true, results: [], count: 0 };

for (const item of ragItems) {
  if (item.json && Array.isArray(item.json)) {
    for (const d of item.json) {
      if (d.id && d.name && d.text) {
        rag.results.push({
          id: d.id,
          name: d.name,
          text: d.text,
          page_hash: d.page_hash || '',
          xywh: d.xywh || '',
          score: d.score || 0
        });
      }
    }
  }
}
rag.count = rag.results.length;

const ansibleContext = ansible.count > 0 
  ? `## Ansible 系統資料\n${ansible.results.slice(0, 10).map(r => `- 主機: ${r.hostname} (${r.ip}), 套件: ${r.package_name}, 版本: ${r.version}`).join('\n')}`
  : '';

const ragContext = rag.count > 0
  ? `## RAG 知識庫文檔\n${rag.results.slice(0, 3).map(r => `- ${r.name}: ${r.text}`).join('\n')}`
  : '';

const systemPrompt = '你是一個專業的智慧運維助手，擅長回答 Ansible 系統管理和技術文檔相關問題。請根據提供的參考資料，用繁體中文簡潔準確地回答用戶問題。';
const userContent = `問題：${question}\n\n參考資料：\n${ansibleContext}\n${ragContext}`;

return {
  json: {
    question: question,
    unit: unit,
    intent: intent,
    ansible: ansible,
    rag: rag,
    system_prompt: systemPrompt,
    user_content: userContent
  }
};

// 直接從前一個節點的輸出中取得資料
const llmResponse = $input.item.json;
const mergeNode = $('整合結果');

if (!mergeNode || !mergeNode.first()) {
  return {
    json: {
      error: '無法取得整合結果',
      text: '系統錯誤，請稍後再試',
      answer: '系統錯誤，請稍後再試',
      citations: []
    }
  };
}

const mergedData = mergeNode.first().json;
const answer = llmResponse.choices && llmResponse.choices[0] && llmResponse.choices[0].message 
  ? llmResponse.choices[0].message.content 
  : '無法生成回答';

return {
  json: {
    text: answer,
    answer: answer,
    citations: mergedData.rag.results || [],
    meta: {
      question: mergedData.question,
      intent: mergedData.intent,
      unit: mergedData.unit,
      ansible_count: mergedData.ansible.count,
      rag_count: mergedData.rag.count
    }
  }
};
